"""Statistics over the words of a text."""


def _words(text):
    """Split text into words.

    A word is a maximal run of letters and digits (``str.isalnum``). An
    apostrophe ``'`` between two such characters is part of the word, so
    ``don't`` is one word and ``'quoted'`` yields the word ``quoted``.
    Everything else separates words.
    """
    words = []
    i = 0
    n = len(text)
    while i < n:
        if text[i].isalnum():
            j = i
            cur = []
            while j < n:
                c = text[j]
                if c.isalnum():
                    cur.append(c)
                    j += 1
                elif c == "'" and j + 1 < n and text[j + 1].isalnum():
                    cur.append(c)
                    j += 1
                else:
                    break
            words.append("".join(cur))
            i = j
        else:
            i += 1
    return words


def average_word_length(text):
    words = _words(text)
    if not words:
        return 0.0
    return sum(len(word) for word in words) / len(words)


def longest_word(text):
    best = ""
    for word in _words(text):
        if len(word) > len(best):
            best = word
    return best


def word_frequencies(text):
    counts = {}
    for word in _words(text):
        word = word.lower()
        counts[word] = counts.get(word, 0) + 1
    return sorted(counts.items(), key=lambda item: (-item[1], item[0]))
